#!/usr/bin/env bash
# Plants the "Deploy to kind" challenge scaffold.
# Idempotent — re-running overwrites source files.
set -euo pipefail

WORK="$HOME/.kube-dojo-work/06-deploy-to-kind"
mkdir -p "$WORK/k8s"

# ── main.py — complete FastAPI app ───────────────────────────────────────────
cat > "$WORK/main.py" << 'PYEOF'
# main.py — complete FastAPI app for the deploy-to-kind challenge.
# Do NOT edit this file; the verifier expects these exact endpoints.
from fastapi import FastAPI

app = FastAPI(title="Dojo API", version="1.0.0")


@app.get("/health", status_code=200)
def health():
    return {"status": "ok"}


@app.get("/ready", status_code=200)
def ready():
    # In a real app this would check the DB connection.
    return {"status": "ready"}


@app.get("/")
def root():
    return {"message": "FastAPI dojo — deployed to kind"}
PYEOF

# ── requirements.txt ─────────────────────────────────────────────────────────
cat > "$WORK/requirements.txt" << 'EOF'
fastapi==0.115.0
uvicorn[standard]==0.30.6
EOF

# ── .dockerignore ────────────────────────────────────────────────────────────
cat > "$WORK/.dockerignore" << 'EOF'
.venv/
__pycache__/
*.pyc
*.pyo
.git/
.env
k8s/
EOF

# ── Dockerfile skeleton ──────────────────────────────────────────────────────
cat > "$WORK/Dockerfile" << 'EOF'
# Dockerfile — fix the two TODO items before building.

# ── Stage 1: dependency builder ──────────────────────────────────────────────
FROM python:3.12-slim AS builder

WORKDIR /build
COPY requirements.txt .
RUN pip install --upgrade pip \
    && pip install --no-cache-dir --prefix=/install -r requirements.txt


# ── Stage 2: runtime ─────────────────────────────────────────────────────────
FROM python:3.12-slim AS runtime

WORKDIR /app

COPY --from=builder /install /usr/local
COPY . .

# TODO 1: Add ENV PYTHONDONTWRITEBYTECODE=1 and PYTHONUNBUFFERED=1 so Python
#         does not try to write .pyc files at startup (which fails under
#         readOnlyRootFilesystem: true).

# TODO 2: Create a non-root system user named "app" and switch to it.
#         Pattern:
#           RUN addgroup --system app && adduser --system --ingroup app app
#           USER app

EXPOSE 8000

CMD ["uvicorn", "main:app", "--host", "0.0.0.0", "--port", "8000"]
EOF

# ── k8s/deployment.yaml skeleton ─────────────────────────────────────────────
cat > "$WORK/k8s/deployment.yaml" << 'EOF'
apiVersion: apps/v1
kind: Deployment
metadata:
  name: fastapi-dojo
  namespace: dojo-fastapi
spec:
  replicas: 1
  selector:
    matchLabels:
      app: fastapi-dojo
  template:
    metadata:
      labels:
        app: fastapi-dojo
    spec:
      containers:
      - name: api
        # TODO: set image to the tag you built, e.g. fastapi-dojo:1.0.0
        image: CHANGE_ME
        # TODO: set imagePullPolicy so kind-loaded images are used without a registry pull
        imagePullPolicy: Always
        ports:
        - containerPort: 8000
        # TODO: add a readinessProbe that sends GET /health to port 8000
        #       initialDelaySeconds: 5, periodSeconds: 5
        resources:
          requests:
            cpu: "100m"
            memory: "64Mi"
          limits:
            cpu: "250m"
            memory: "128Mi"
        # TODO: add a securityContext with readOnlyRootFilesystem: true and runAsNonRoot: true
      # TODO: add a volume named "tmp" of type emptyDir and mount it at /tmp
      #       (Python still needs a scratch directory even with readOnlyRootFilesystem)
EOF

# ── k8s/service.yaml skeleton ────────────────────────────────────────────────
cat > "$WORK/k8s/service.yaml" << 'EOF'
apiVersion: v1
kind: Service
metadata:
  name: fastapi-dojo
  namespace: dojo-fastapi
spec:
  # TODO: add selector matching the deployment's pod labels (app: fastapi-dojo)
  ports:
  - port: 80
    targetPort: 8000
    protocol: TCP
  type: ClusterIP
EOF

echo
echo "Work directory : $WORK"
echo
echo "Task           : fix Dockerfile (2 TODOs), fill in k8s/deployment.yaml (4 TODOs)"
echo "                 and k8s/service.yaml (1 TODO), then build + deploy."
echo
echo "Prerequisites  : Docker Desktop running + kind-dojo cluster active"
echo "  kubectl config current-context   # -> kind-dojo"
echo
echo "Build + deploy :"
echo "  cd $WORK"
echo "  docker build -t fastapi-dojo:1.0.0 ."
echo "  kind load docker-image fastapi-dojo:1.0.0 --name dojo"
echo "  kubectl create namespace dojo-fastapi --dry-run=client -o yaml | kubectl apply -f -"
echo "  kubectl apply -f k8s/"
echo "  kubectl rollout status deployment/fastapi-dojo -n dojo-fastapi"
echo
echo "Verify + flag  : bash courses/course-15-fastapi-production/challenges/06-deploy-to-kind/verify.sh"
